// src/lib/nova-tables.ts — Nova's real database: tables, rows, links.
//
// Generated by Nova. Typed by ./nova-schema.ts, which Nova regenerates from
// the site's data model; a table or column that doesn't exist is a type error.
//
//   import { tables, useTable } from './lib/nova-tables'
//
//   const { rows, loading, error, reload } = useTable('bookings', { sort: '-starts_at' })
//   await tables.insert('bookings', { service_id, starts_at })
//   await tables.update('bookings', id, { note })
//   const { rows: withService } = await tables.list('bookings', { include: ['service'] })
//
// Who may read or change what is decided on the server, by the rules in the
// data model. A request it refuses rejects with a NovaTableError whose `code`
// says why ('sign_in_required', 'forbidden_by_rule', ...): show the user a
// message, never retry a write.
import { useCallback, useEffect, useState } from 'react'
import type { TableName, Tables } from './nova-schema'

export type Row<T extends TableName> = Tables[T]['row']
export type Insert<T extends TableName> = Tables[T]['insert']
export type Update<T extends TableName> = Tables[T]['update']

export interface TableQuery<T extends TableName> {
  /** Exact matches, ANDed. `null` matches empty. At most 8. */
  where?: Partial<{ [K in keyof Row<T>]: Row<T>[K] | null }>
  /** A column name; prefix with '-' for newest/largest first. Default '-created_at'. */
  sort?: string
  /** Default 50, at most 200. */
  limit?: number
  offset?: number
  /** Links to load with each row, e.g. ['service'] for a service_id column. */
  include?: string[]
}

export interface TablePage<T extends TableName> {
  rows: Row<T>[]
  limit: number
  offset: number
  has_more: boolean
}

export class NovaTableError extends Error {
  status: number
  code: string
  constructor(message: string, status: number, code: string) {
    super(message)
    this.name = 'NovaTableError'
    this.status = status
    this.code = code
  }
}

function config(): { api?: string; branch?: string; branchToken?: string; projectId?: string } {
  return ((window as any).__NOVA_APP_DB__ as any) || {}
}

// The branch token is signed into the page when it is served, and it expires
// (1 h for test data, 24 h for live). A page left open longer asks for a fresh
// one once: live data from the public endpoint; test data from the NOVA
// workspace around the preview, since the preview frame can't send a login.
let refreshing: Promise<boolean> | null = null

function askWorkspace(): Promise<string> {
  return new Promise((resolve) => {
    if (window.parent === window) return resolve('')
    const done = (token: string) => {
      window.removeEventListener('message', onMessage)
      clearTimeout(timer)
      resolve(token)
    }
    const onMessage = (e: MessageEvent) => {
      if (e.source !== window.parent || e.data?.type !== 'NOVA_APP_DB_TOKEN') return
      done(typeof e.data.token === 'string' ? e.data.token : '')
    }
    const timer = setTimeout(() => done(''), 5000)
    window.addEventListener('message', onMessage)
    window.parent.postMessage({ type: 'NOVA_APP_DB_TOKEN' }, '*')
  })
}

async function fetchToken(base: string, branch: string): Promise<string> {
  if (branch === 'preview') return askWorkspace()
  try {
    const res = await fetch(base + '/api/app/' + encodeURIComponent(projectId()) + '/branch-token?branch=main')
    const body = res.ok ? await res.json() : null
    return typeof body?.token === 'string' ? body.token : ''
  } catch {
    return ''
  }
}

function refreshToken(base: string): Promise<boolean> {
  if (!refreshing) {
    const cfg = config()
    refreshing = fetchToken(base, cfg.branch || 'main').then((token) => {
      if (token) cfg.branchToken = token
      return !!token
    }).finally(() => { setTimeout(() => { refreshing = null }, 0) })
  }
  return refreshing
}

function projectId(): string {
  const id = (window as any).novaDB?.projectId || config().projectId
  if (!id) throw new NovaTableError('Nova backend unavailable.', 0, 'no_runtime')
  return id
}

async function call<R>(method: string, path: string, body?: unknown, retried = false): Promise<R> {
  const cfg = config()
  const base = cfg.api ? cfg.api.replace(/\/$/, '') : ''
  const auth = (window as any).novaDB?._authHeaders
  const headers: Record<string, string> = auth ? auth({}) : {}
  if (body !== undefined) headers['Content-Type'] = 'application/json'
  if (cfg.branchToken) headers['X-Nova-Branch'] = cfg.branchToken
  let res: Response
  try {
    res = await fetch(base + '/api/app/' + encodeURIComponent(projectId()) + path, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
    })
  } catch {
    throw new NovaTableError('Could not reach the database.', 0, 'network')
  }
  let payload: any = null
  try { payload = await res.json() } catch { /* empty body */ }
  if (!res.ok) {
    const d = payload?.detail
    const message = typeof d === 'string' ? d : d?.message || 'Request failed.'
    const code = (typeof d === 'object' && d?.code) || 'http_' + res.status
    // The server refused the token before running anything, so even a write
    // is safe to send again -- once.
    if (code === 'branch_token_expired' && !retried && cfg.branchToken && await refreshToken(base)) {
      return call<R>(method, path, body, true)
    }
    // A page bug (a table or field that doesn't exist, a malformed value, the
    // database down) is logged with its code so Nova's checks can name it.
    // Expected answers -- not signed in, not allowed, not found -- are not.
    if (!EXPECTED.has(code)) console.error('[nova-tables] ' + code + ': ' + message + ' (' + method + ' ' + path.split('?')[0] + ')')
    throw new NovaTableError(message, res.status, code)
  }
  return payload as R
}

function qs<T extends TableName>(q: TableQuery<T> = {}): string {
  const p = new URLSearchParams()
  if (q.where && Object.keys(q.where).length) p.set('where', JSON.stringify(q.where))
  if (q.sort) p.set('sort', q.sort)
  if (q.limit !== undefined) p.set('limit', String(q.limit))
  if (q.offset !== undefined) p.set('offset', String(q.offset))
  if (q.include?.length) p.set('include', q.include.join(','))
  const s = p.toString()
  return s ? '?' + s : ''
}

const EXPECTED = new Set(['sign_in_required', 'forbidden_by_rule', 'not_found', 'rate_limited'])

export interface TeamMember { id: string; email: string; name: string; role: string }

/**
 * For an admin page that manages people. A signed-in user can only manage
 * accounts BELOW their own role: they cannot change themselves, promote
 * anyone to their own level or above, or touch the site's owner. The server
 * enforces that; this just calls it. Needs the site to declare its roles.
 */
export const team = {
  /** The people you may manage, and the roles you may give them. */
  async list(): Promise<{ users: TeamMember[]; roles: string[] }> {
    return await call('GET', '/admin/users')
  },
  async setRole(userId: string, role: string): Promise<{ ok: true; role: string }> {
    return await call('PUT', '/admin/users/' + encodeURIComponent(userId) + '/role', { role })
  },
  async remove(userId: string): Promise<{ ok: true }> {
    return await call('DELETE', '/admin/users/' + encodeURIComponent(userId))
  },
}

const t = (name: string) => '/t/' + encodeURIComponent(name)

export const tables = {
  async list<T extends TableName>(table: T, query: TableQuery<T> = {}): Promise<TablePage<T>> {
    return await call<TablePage<T>>('GET', t(table) + qs(query))
  },
  async get<T extends TableName>(table: T, id: string, include?: string[]): Promise<Row<T>> {
    return await call<Row<T>>('GET', t(table) + '/' + encodeURIComponent(id) + qs({ include }))
  },
  /** Create a row. Resolves to the row, or { ok: true } on write-only tables. */
  async insert<T extends TableName>(table: T, data: Insert<T>): Promise<Row<T> | { ok: true }> {
    return await call('POST', t(table), { data })
  },
  async update<T extends TableName>(table: T, id: string, data: Update<T>): Promise<Row<T>> {
    return await call<Row<T>>('PATCH', t(table) + '/' + encodeURIComponent(id), { data })
  },
  async remove<T extends TableName>(table: T, id: string): Promise<{ ok: true; id: string }> {
    return await call('DELETE', t(table) + '/' + encodeURIComponent(id))
  },
  /** Same as insert. Here so `tables.create(...)` works as well. */
  async create<T extends TableName>(table: T, data: Insert<T>): Promise<Row<T> | { ok: true }> {
    return await call('POST', t(table), { data })
  },
  /** Same as remove. Here so `tables.delete(...)` works as well. */
  async delete<T extends TableName>(table: T, id: string): Promise<{ ok: true; id: string }> {
    return await call('DELETE', t(table) + '/' + encodeURIComponent(id))
  },
}

/** A table, loaded and kept in state. Call `reload` after you write. */
export function useTable<T extends TableName>(table: T, query: TableQuery<T> = {}) {
  const [rows, setRows] = useState<Row<T>[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<NovaTableError | null>(null)
  const key = JSON.stringify(query)
  const reload = useCallback(async () => {
    setLoading(true)
    try {
      const page = await tables.list(table, JSON.parse(key))
      setRows(page.rows)
      setError(null)
    } catch (e) {
      setError(e instanceof NovaTableError ? e : new NovaTableError(String(e), 0, 'unknown'))
    } finally {
      setLoading(false)
    }
  }, [table, key])
  useEffect(() => { reload() }, [reload])
  return { rows, loading, error, reload }
}
